class Solution {
public:
    vector<int> assignBikes(vector<vector<int>>& workers, vector<vector<int>>& bikes) {
        int n = workers.size(), m = bikes.size();
        vector<vector<pair<int, int>>> buckets(2001);
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                int d = abs(workers[i][0] - bikes[j][0]) + abs(workers[i][1] - bikes[j][1]);
                buckets[d].push_back({i, j});
            }
        }

        vector<int> res(n, -1);
        vector<bool> bike_used(m, false);
        int assigned = 0;
        for (int d = 0; d <= 2000; ++d) {
            for (const auto& p : buckets[d]) {
                int w = p.first, b = p.second;
                if (res[w] == -1 && !bike_used[b]) {
                    res[w] = b;
                    bike_used[b] = true;
                    assigned++;
                    if (assigned == n) return res;
                }
            }
        }
        return res;
    }
};

class Solution {
    public int[] assignBikes(int[][] workers, int[][] bikes) {
        int n = workers.length, m = bikes.length;
        List<int[]>[] buckets = new ArrayList[2001];
        for (int d = 0; d <= 2000; ++d) buckets[d] = new ArrayList<>();

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                int d = Math.abs(workers[i][0] - bikes[j][0]) + Math.abs(workers[i][1] - bikes[j][1]);
                buckets[d].add(new int[]{i, j});
            }
        }

        int[] res = new int[n];
        Arrays.fill(res, -1);
        boolean[] bikeUsed = new boolean[m];
        int assigned = 0;

        for (int d = 0; d <= 2000; ++d) {
            for (int[] p : buckets[d]) {
                int w = p[0], b = p[1];
                if (res[w] == -1 && !bikeUsed[b]) {
                    res[w] = b;
                    bikeUsed[b] = true;
                    assigned++;
                    if (assigned == n) return res;
                }
            }
        }
        return res;
    }
}

var assignBikes = function(workers, bikes) {
    const buckets = Array.from({ length: 2001 }, () => []);
    const n = workers.length, m = bikes.length;
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < m; j++) {
            const d = Math.abs(workers[i][0] - bikes[j][0]) + Math.abs(workers[i][1] - bikes[j][1]);
            buckets[d].push([i, j]);
        }
    }

    const res = new Array(n).fill(-1);
    const bikeUsed = new Array(m).fill(false);
    let assigned = 0;
    for (let d = 0; d <= 2000; d++) {
        for (const [w, b] of buckets[d]) {
            if (res[w] === -1 && !bikeUsed[b]) {
                res[w] = b;
                bikeUsed[b] = true;
                assigned++;
                if (assigned === n) return res;
            }
        }
    }
    return res;
};
